    private static function e164(string $value): string {$digits=preg_replace('/\D+/','',$value);if(!is_string($digits)||!preg_match('/^[0-9]{7,15}$/',$digits))throw new \InvalidArgumentException('Номер должен быть в международном формате.');return '+'.$digits;}
