    private static function rememberCall(array $row): void {$calls=get_option(self::CALLS_OPTION,[]);if(!is_array($calls))$calls=[];array_unshift($calls,$row);$calls=array_slice($calls,0,200);update_option(self::CALLS_OPTION,$calls,false);}
