    private static function header(array $headers,string $name): string {$wanted=str_replace('_','-',strtolower($name));foreach($headers as $k=>$v){$actual=str_replace('_','-',strtolower((string)$k));if($actual===$wanted)return is_array($v)?(string)reset($v):(string)$v;}return '';}
